// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes memory data, uint256 msgVal) public {
        vm.assume(adr != address(0) && adr != address(c));
        vm.assume(data.length > 0);
        uint256 initContractBalance = address(c).balance;
        uint256 initMultiplicateBalance = address(adr).balance;
        vm.deal(address(c), 1 ether); // ensure contract has some balance
        vm.deal(address(this), msgVal);
        // call Command with msg.value = msgVal
        (bool success, ) = address(c).call{value: msgVal}(abi.encodeWithSignature("Command(address,bytes)", adr, data));
        vm.assume(success); // only consider successful calls
        uint256 finalContractBalance = address(c).balance;
        uint256 finalMultiplicateBalance = address(adr).balance;
        // General rule: after Command, the contract's balance plus the msg.value sent is at least the initial multiplicate balance plus msg.value
        assertTrue(finalContractBalance + msgVal >= initMultiplicateBalance + msgVal);
    }
}

